toolArgs.file_text:
@using sv_ac5aee119ee947fa84a5c60719aae3a5.Models
@using sv_ac5aee119ee947fa84a5c60719aae3a5.Services
@inject ISettingsService SettingsService

<div class="notifications-section">
    <h4 class="mb-4">Notification Preferences</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading preferences…</p>
    }
    else
    {
        <div class="card mb-4">
            <div class="card-body">
                <h6 class="card-title mb-3">Notification Channels</h6>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                    <label class="form-check-label" for="emailNotif">
                        <strong>Email Notifications</strong>
                        <br /><small class="text-muted">Receive notifications via email</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                    <label class="form-check-label" for="pushNotif">
                        <strong>Push Notifications</strong>
                        <br /><small class="text-muted">Receive browser push notifications</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                    <label class="form-check-label" for="weeklyDigest">
                        <strong>Weekly Digest</strong>
                        <br /><small class="text-muted">Get a weekly summary of activity</small>
                    </label>
                </div>
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-body">
                <h6 class="card-title mb-3">Muted Channels</h6>
                <p class="text-muted small">Uncheck channels you want to mute.</p>

                @foreach (var channel in _allChannels)
                {
                    var isMuted = _mutedChannels.Contains(channel);
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox"
                               id="@($"ch-{channel}")"
                               checked="@(!isMuted)"
                               @onchange="e => ToggleChannel(channel, e)" />
                        <label class="form-check-label" for="@($"ch-{channel}")">
                            #@channel
                            @if (isMuted)
                            {
                                <span class="badge bg-secondary ms-2">Muted</span>
                            }
                        </label>
                    </div>
                }
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving…" : "Save Preferences")
        </button>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3 d-flex align-items-center" role="alert">
                <span class="me-2">✅</span> Notification preferences saved!
            </div>
        }
    }
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _mutedChannels = new();
    private List<string> _allChannels = new();
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _allChannels = new List<string>(prefs.MutedChannels);
        _mutedChannels = new List<string>();
        _loading = false;
    }

    private void ToggleChannel(string channel, ChangeEventArgs e)
    {
        var isChecked = (bool)(e.Value ?? false);
        if (isChecked)
        {
            _mutedChannels.Remove(channel);
        }
        else
        {
            if (!_mutedChannels.Contains(channel))
                _mutedChannels.Add(channel);
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
