@using sv_ac5aee119ee947fa84a5c60719aae3a5.Models

<div class="card mb-3">
    <div class="card-header fw-semibold">📱 Active Sessions</div>
    <div class="card-body p-0">
        <div class="table-responsive">
            <table class="table table-hover mb-0">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        var isCurrent = session.Id == CurrentSessionId;
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="badge bg-success ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (!isCurrent)
                                {
                                    <button class="btn btn-outline-danger btn-sm"
                                            @onclick="() => OnRevokeRequested.InvokeAsync(session.Id)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevokeRequested { get; set; }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@if (Visible)
{
    <div class="modal-backdrop show" @onclick="Cancel"></div>
    <div class="modal d-block" tabindex="-1">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="Confirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool Visible { get; set; }
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm() => await OnConfirm.InvokeAsync();
    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@using sv_ac5aee119ee947fa84a5c60719aae3a5.Models
@using sv_ac5aee119ee947fa84a5c60719aae3a5.Services
@inject ISettingsService SettingsService

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading security settings…</p>
    }
    else
    {
        <ChangePasswordPanel OnChangePassword="HandleChangePasswordAsync" />

        <div class="card mb-3">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <small class="text-muted">Add an extra layer of security to your account</small>
                </div>
                <div class="d-flex align-items-center gap-2">
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                    <div class="form-check form-switch mb-0">
                        <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                    </div>
                </div>
            </div>
        </div>

        @if (_lastPasswordChange.HasValue)
        {
            <p class="text-muted small mb-3">
                Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }

        <ActiveSessionsTable Sessions="_sessions"
                             CurrentSessionId="@_currentSessionId"
                             OnRevokeRequested="RequestRevoke" />

        <RevokeSessionDialog Visible="_showRevokeDialog"
                             OnConfirm="ConfirmRevokeAsync"
                             OnCancel="CancelRevoke" />
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private string _currentSessionId = "sess-1"; // First session is "current"
    private bool _showRevokeDialog;
    private string? _pendingRevokeId;

    protected override async Task OnInitializedAsync()
    {
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        _loading = false;
    }

    private async Task HandleChangePasswordAsync((string current, string newPw) args)
    {
        await SettingsService.ChangePasswordAsync(args.current, args.newPw);
        _lastPasswordChange = DateTime.UtcNow;
    }

    private void RequestRevoke(string sessionId)
    {
        _pendingRevokeId = sessionId;
        _showRevokeDialog = true;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_pendingRevokeId is not null)
        {
            await SettingsService.RevokeSessionAsync(_pendingRevokeId);
            _sessions.RemoveAll(s => s.Id == _pendingRevokeId);
        }
        _showRevokeDialog = false;
        _pendingRevokeId = null;
    }

    private void CancelRevoke()
    {
        _showRevokeDialog = false;
        _pendingRevokeId = null;
    }
}

