toolArgs.file_text:
@using sv_ac5aee119ee947fa84a5c60719aae3a5.Models
@using sv_ac5aee119ee947fa84a5c60719aae3a5.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (_loading)
    {
        <p class="text-muted">Loading appearance settings…</p>
    }
    else
    {
        <div class="row">
            <div class="col-md-7">
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title mb-3">Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check mb-2">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")"
                                       value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title mb-3">Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")"
                                       value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title mb-3">Language</h6>
                        <select class="form-select" @bind="_language">
                            <option value="English">English</option>
                            <option value="Spanish">Spanish</option>
                            <option value="French">French</option>
                            <option value="German">German</option>
                            <option value="Japanese">Japanese</option>
                            <option value="Chinese">Chinese</option>
                        </select>
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body d-flex justify-content-between align-items-center">
                        <div>
                            <h6 class="mb-1">Compact Mode</h6>
                            <small class="text-muted">Reduce spacing and padding throughout the UI</small>
                        </div>
                        <div class="form-check form-switch mb-0">
                            <input class="form-check-input" type="checkbox" @bind="_compactMode" />
                        </div>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save")
                </button>

                @if (_showSuccess)
                {
                    <div class="alert alert-success mt-3 d-flex align-items-center" role="alert">
                        <span class="me-2">✅</span> Appearance settings saved!
                    </div>
                }
            </div>

            <div class="col-md-5">
                <div class="card">
                    <div class="card-header fw-semibold">Live Preview</div>
                    <div class="card-body preview-area @GetPreviewClasses()">
                        <h6 style="@GetPreviewFontStyle()">Sample Heading</h6>
                        <p style="@GetPreviewFontStyle()">
                            This is a preview of how your content will look with the selected settings.
                        </p>
                        <div class="d-flex gap-2" style="@GetPreviewPadding()">
                            <button class="btn btn-sm btn-primary">Primary</button>
                            <button class="btn btn-sm btn-outline-secondary">Secondary</button>
                        </div>
                        <div class="mt-2">
                            <small class="text-muted">
                                Theme: @_theme · Font: @_fontSize · Lang: @_language · Compact: @(_compactMode ? "On" : "Off")
                            </small>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _saving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private string GetPreviewClasses() => _theme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string GetPreviewFontStyle() => _fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.2rem;",
        _ => "font-size: 1rem;"
    };

    private string GetPreviewPadding() => _compactMode
        ? "padding: 0.25rem 0;"
        : "padding: 0.5rem 0;";
}

.preview-area {
    transition: all 0.2s ease;
    min-height: 150px;
}

.preview-light {
    background-color: #ffffff;
    color: #212529;
}

.preview-dark {
    background-color: #1e1e1e;
    color: #e0e0e0;
}

.preview-dark .btn-primary {
    background-color: #4a9eff;
    border-color: #4a9eff;
}

.preview-dark .text-muted {
    color: #999 !important;
}

